export const LOCKED_SOURCES = {"ros2lab_hardware":["include/ros2lab_hardware/bridge_system.hpp","include/ros2lab_hardware/protocol.hpp","include/ros2lab_hardware/transport.hpp","src/bridge_probe.cpp","src/bridge_system.cpp","src/transport.cpp","test/test_bridge_system.cpp","test/test_protocol.cpp"],"ros2lab_firmware":["ros2lab_bridge/actuators.cpp","ros2lab_bridge/actuators.h","ros2lab_bridge/bridge_core.h","ros2lab_bridge/bridge_proto.h","ros2lab_bridge/imu.h","ros2lab_bridge/ros2lab_bridge.ino"]};
